import type { ResolvedRule } from "../types.js";
import type { VerifySpec } from "../verify/types.js";

export const GENERATED_MARKER =
  "<!-- DO NOT EDIT: generated by `wow sync` from wow/. Edit the source files in wow/ instead. -->";

export type TargetId = "agents-md" | "claude-md" | "copilot-instructions" | "cursorrules";

export interface TargetDefinition {
  path: string;
  heading: string;
}

export const TARGETS: Record<TargetId, TargetDefinition> = {
  "agents-md": { path: "AGENTS.md", heading: "Ways of Working" },
  "claude-md": { path: "CLAUDE.md", heading: "Ways of Working" },
  "copilot-instructions": {
    path: ".github/copilot-instructions.md",
    heading: "Ways of Working",
  },
  cursorrules: { path: ".cursorrules", heading: "Ways of Working" },
};

export const TARGET_IDS = Object.keys(TARGETS) as TargetId[];

const ENFORCEMENT_ORDER = { hard: 0, soft: 1, info: 2 } as const;

const ENFORCEMENT_TEXT = {
  hard: "MUST follow. Non-negotiable; cannot be relaxed by lower levels.",
  soft: "SHOULD follow. Deviate only with a stated reason.",
  info: "Reference context.",
} as const;

function sortRules(rules: ResolvedRule[]): ResolvedRule[] {
  return [...rules].sort((left, right) => {
    const byEnforcement =
      ENFORCEMENT_ORDER[left.frontmatter.enforcement] -
      ENFORCEMENT_ORDER[right.frontmatter.enforcement];
    return byEnforcement || left.frontmatter.id.localeCompare(right.frontmatter.id);
  });
}

function stripLeadingH1(body: string): string {
  return body.replace(/^# .*\n+/, "").trim();
}

function describeVerifier(verify: VerifySpec): string {
  switch (verify.type) {
    case "human":
      return `human review — ${verify.instructions}`;
    case "llm":
      return "LLM review (advisory)";
    default:
      return describeDeterministic(verify);
  }
}

function describeDeterministic(verify: Extract<VerifySpec, { type: "deterministic" }>): string {
  switch (verify.check) {
    case "file-exists":
      return `\`${verify.path}\` must exist`;
    case "file-absent":
      return `\`${verify.path}\` must not exist`;
    case "pattern":
      return `files matching \`${verify.glob}\` must ${verify.mode === "forbid" ? "not contain" : "contain"} ${verify.contains !== undefined ? `"${verify.contains}"` : `/${verify.regex}/`}`;
    case "command":
      return `\`${verify.argv.join(" ")}\` exits ${verify.expect_exit ?? 0}`;
  }
}

function renderRule(rule: ResolvedRule): string {
  const { id, title, enforcement, applies_to, rationale, verify } = rule.frontmatter;
  const lines = [
    `## ${title} (${id})`,
    "",
    `- **Enforcement:** ${enforcement} — ${ENFORCEMENT_TEXT[enforcement]}`,
    `- **Applies to:** ${applies_to.join(", ")}`,
  ];
  if (rationale) {
    lines.push(`- **Rationale:** ${rationale}`);
  }
  if (verify) {
    lines.push(`- **Verified by:** ${describeVerifier(verify)}`);
  }
  lines.push("", stripLeadingH1(rule.body));
  return lines.join("\n");
}

/** Rules as markdown sections (hard, soft, info), without header marker or title. */
export function renderRuleSections(rules: ResolvedRule[]): string {
  return sortRules(rules).map(renderRule).join("\n\n");
}

export function renderTarget(rules: ResolvedRule[], target: TargetId): string {
  const { heading } = TARGETS[target];
  const sections = renderRuleSections(rules);
  const body = sections ? `\n\n${sections}` : "";
  return `${GENERATED_MARKER}\n\n# ${heading}${body}\n`;
}
